const $ = (id) => document.getElementById(id);
class ApiError extends Error { constructor(message,status,detail){super(message);this.status=status;this.detail=detail;} }

const state = {
  map:null, draw:null, mapReady:false, workspace:null, book:null, plan:null,
  availableBooks:[], selectedBooks:new Set(), visibleBooks:new Set(), visibleRoutes:new Set(),
  visibleDemarcations:new Set(), visiblePlannedRoutes:new Set(),
  showPendingPoints:true, showPlannedPoints:true,
  sequence:[], editingRouteId:null, ucById:new Map(), assigned:new Map(), bookBounds:null,
  polygonFound:[], polygonChecked:new Set(), currentDemarcationId:null,
  demarcations:new Map(), editingDrawId:null, suppressDrawEvents:false,
  previewOrder:[], previewContext:'sequence', moveConflictsOnSave:false,
  autosaveTimer:null, settingsTimer:null, saveInFlight:false, dirty:false,
  isolatedSnapshot:null, searchFeatureId:null
};

const DEMARCATION_COLORS=['#38bdf8','#22c55e','#f59e0b','#a78bfa','#f43f5e','#14b8a6','#eab308','#fb7185'];
function toast(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2800)}
function status(msg){$('statusPill').textContent=msg}
function setAutosave(text,cls=''){const p=$('autosavePill');p.textContent=text;p.className='autosave-pill '+cls}
async function api(url,opts={}){const res=await fetch(url,{headers:{'Content-Type':'application/json',...(opts.headers||{})},...opts});if(!res.ok){let raw=await res.text(),detail=raw;try{detail=JSON.parse(raw).detail}catch{};const msg=typeof detail==='string'?detail:(detail?.message||raw);throw new ApiError(msg,res.status,detail)}const ct=res.headers.get('content-type')||'';return ct.includes('json')?res.json():res}
function esc(s){return String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function fmtKm(m){if(m==null)return '—';return m<1000?`${Math.round(m)} m`:`${(m/1000).toFixed(2)} km`}
function fmtMin(min){if(min==null)return '—';const n=Math.round(Number(min));return n<60?`${n} min`:`${Math.floor(n/60)}h${String(n%60).padStart(2,'0')}`}
function emptyFC(){return {type:'FeatureCollection',features:[]}}
function routeColor(id){const colors=['#22c55e','#f97316','#a78bfa','#f43f5e','#14b8a6','#eab308','#38bdf8','#fb7185'];let n=0;for(const c of String(id??''))n+=c.charCodeAt(0);return colors[Math.abs(n)%colors.length]}
function selectedBooksArray(){return [...state.selectedBooks].map(Number).sort((a,b)=>a-b)}
function sameBooks(a,b){const x=[...a].map(Number).sort((m,n)=>m-n),y=[...b].map(Number).sort((m,n)=>m-n);return x.length===y.length&&x.every((v,i)=>v===y[i])}
function routeKey(livro,rota){return `${Number(livro)}::${String(rota??'')}`}

function initMap(){
  const style={version:8,sources:{
    fallback:{type:'raster',tiles:['https://tile.openstreetmap.org/{z}/{x}/{y}.png'],tileSize:256,attribution:'© OpenStreetMap contributors'},
    satellite:{type:'raster',tiles:['https://services.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}'],tileSize:256,attribution:'Esri World Imagery'}
  },layers:[{id:'fallback',type:'raster',source:'fallback'},{id:'satellite',type:'raster',source:'satellite',paint:{'raster-opacity':1}}]};
  state.map=new maplibregl.Map({container:'map',style,center:[-56.1,-15.6],zoom:5,attributionControl:true,maxZoom:20});
  state.map.addControl(new maplibregl.NavigationControl({visualizePitch:true}),'bottom-right');
  state.map.on('load',()=>{state.mapReady=true;setupOperationalLayers();setupDraw();});
  state.map.on('error',e=>{const msg=String(e?.error?.message||'');if(msg.includes('raster')||msg.includes('tile'))console.warn('Tile map error',msg)});
}
function addGeoSource(id,data,opts={}){if(!state.map.getSource(id))state.map.addSource(id,{type:'geojson',data,...opts})}
function setupOperationalLayers(){
  const m=state.map;
  addGeoSource('book-area',emptyFC());addGeoSource('route-areas',emptyFC());addGeoSource('demarcations',emptyFC());
  addGeoSource('ucs',emptyFC(),{cluster:true,clusterMaxZoom:13,clusterRadius:42});
  addGeoSource('sequence-line',emptyFC());addGeoSource('sequence-points',emptyFC());addGeoSource('saved-routes',emptyFC());
  addGeoSource('road-preview',emptyFC());addGeoSource('polygon-found',emptyFC());addGeoSource('polygon-selected',emptyFC());addGeoSource('search-highlight',emptyFC());
  m.addLayer({id:'book-fill',type:'fill',source:'book-area',paint:{'fill-color':['coalesce',['get','color'],'#fbbf24'],'fill-opacity':0.055}});
  m.addLayer({id:'book-outline',type:'line',source:'book-area',paint:{'line-color':['coalesce',['get','color'],'#fbbf24'],'line-width':3,'line-dasharray':[2,1]}});
  m.addLayer({id:'route-fill',type:'fill',source:'route-areas',paint:{'fill-color':['get','color'],'fill-opacity':0.13}});
  m.addLayer({id:'route-outline',type:'line',source:'route-areas',paint:{'line-color':['get','color'],'line-width':2.5,'line-opacity':0.95}});
  m.addLayer({id:'demarcation-fill',type:'fill',source:'demarcations',paint:{'fill-color':['get','color'],'fill-opacity':0.10}});
  m.addLayer({id:'demarcation-outline',type:'line',source:'demarcations',paint:{'line-color':['get','color'],'line-width':3}});
  m.addLayer({id:'clusters',type:'circle',source:'ucs',filter:['has','point_count'],paint:{'circle-color':'#0c4a6e','circle-radius':['step',['get','point_count'],18,100,24,500,30],'circle-stroke-color':'#7dd3fc','circle-stroke-width':2,'circle-opacity':0.9}});
  m.addLayer({id:'cluster-count',type:'symbol',source:'ucs',filter:['has','point_count'],layout:{'text-field':['get','point_count_abbreviated'],'text-size':11},paint:{'text-color':'#e0f2fe'}});
  m.addLayer({id:'uc-points',type:'circle',source:'ucs',filter:['!',['has','point_count']],paint:{'circle-color':['coalesce',['get','displayColor'],['get','color'],'#e2e8f0'],'circle-radius':['interpolate',['linear'],['zoom'],10,3,15,6,18,8],'circle-stroke-color':['case',['get','assigned'],'#fde68a','#ffffff'],'circle-stroke-width':['case',['get','assigned'],2.2,1.0],'circle-opacity':0.96}});
  m.addLayer({id:'polygon-found',type:'circle',source:'polygon-found',paint:{'circle-color':'rgba(0,0,0,0)','circle-radius':9,'circle-stroke-color':'#fbbf24','circle-stroke-width':2}});
  m.addLayer({id:'polygon-selected',type:'circle',source:'polygon-selected',paint:{'circle-color':'#f59e0b','circle-radius':7,'circle-stroke-color':'#fff7ed','circle-stroke-width':2}});
  m.addLayer({id:'saved-routes',type:'line',source:'saved-routes',paint:{'line-color':['get','color'],'line-width':5,'line-opacity':0.78}});
  m.addLayer({id:'sequence-line',type:'line',source:'sequence-line',paint:{'line-color':'#22d3ee','line-width':5,'line-opacity':0.95}});
  m.addLayer({id:'road-preview',type:'line',source:'road-preview',paint:{'line-color':'#f43f5e','line-width':4,'line-dasharray':[1.5,1.2]}});
  m.addLayer({id:'sequence-points',type:'circle',source:'sequence-points',paint:{'circle-color':'#22d3ee','circle-radius':8,'circle-stroke-color':'#001018','circle-stroke-width':2}});
  m.addLayer({id:'sequence-labels',type:'symbol',source:'sequence-points',layout:{'text-field':['to-string',['get','order']],'text-size':10},paint:{'text-color':'#001018'}});
  m.addLayer({id:'search-highlight',type:'circle',source:'search-highlight',paint:{'circle-color':'rgba(255,255,255,0)','circle-radius':14,'circle-stroke-color':'#ef4444','circle-stroke-width':4}});
  m.on('click','clusters',async e=>{const f=e.features[0],src=m.getSource('ucs');const z=await src.getClusterExpansionZoom(f.properties.cluster_id);m.easeTo({center:f.geometry.coordinates,zoom:z})});
  m.on('click','uc-points',e=>handleUcClick(e.features[0]));
  m.on('mouseenter','uc-points',()=>m.getCanvas().style.cursor='pointer');m.on('mouseleave','uc-points',()=>m.getCanvas().style.cursor='');
}
const drawStyles=[
  {id:'gl-draw-polygon-fill-inactive',type:'fill',filter:['all',['==','active','false'],['==','$type','Polygon'],['!=','mode','static']],paint:{'fill-color':'#38bdf8','fill-outline-color':'#38bdf8','fill-opacity':0.13}},
  {id:'gl-draw-polygon-fill-active',type:'fill',filter:['all',['==','active','true'],['==','$type','Polygon']],paint:{'fill-color':'#fbbf24','fill-outline-color':'#fbbf24','fill-opacity':0.16}},
  {id:'gl-draw-polygon-stroke-inactive',type:'line',filter:['all',['==','active','false'],['==','$type','Polygon'],['!=','mode','static']],layout:{'line-cap':'round','line-join':'round'},paint:{'line-color':'#38bdf8','line-width':2}},
  {id:'gl-draw-polygon-stroke-active',type:'line',filter:['all',['==','active','true'],['==','$type','Polygon']],layout:{'line-cap':'round','line-join':'round'},paint:{'line-color':'#fbbf24','line-dasharray':[0.2,2],'line-width':2}},
  {id:'gl-draw-polygon-midpoint',type:'circle',filter:['all',['==','$type','Point'],['==','meta','midpoint']],paint:{'circle-radius':3,'circle-color':'#fbbf24'}},
  {id:'gl-draw-polygon-and-line-vertex-stroke-inactive',type:'circle',filter:['all',['==','meta','vertex'],['==','$type','Point'],['!=','mode','static']],paint:{'circle-radius':5,'circle-color':'#fff'}},
  {id:'gl-draw-polygon-and-line-vertex-inactive',type:'circle',filter:['all',['==','meta','vertex'],['==','$type','Point'],['!=','mode','static']],paint:{'circle-radius':3,'circle-color':'#fbbf24'}}
];
function setupDraw(){
  if(typeof MapboxDraw==='undefined')return;
  MapboxDraw.constants.classes.CANVAS='maplibregl-canvas';MapboxDraw.constants.classes.CONTROL_BASE='maplibregl-ctrl';MapboxDraw.constants.classes.CONTROL_PREFIX='maplibregl-ctrl-';MapboxDraw.constants.classes.CONTROL_GROUP='maplibregl-ctrl-group';MapboxDraw.constants.classes.ATTRIBUTION='maplibregl-ctrl-attrib';
  state.draw=new MapboxDraw({displayControlsDefault:false,controls:{},styles:drawStyles});state.map.addControl(state.draw);
  state.map.on('draw.create',onDrawCreate);state.map.on('draw.update',onDrawUpdate);state.map.on('draw.delete',onDrawDelete);
}
function clearDrawEditor(){if(!state.draw)return;state.suppressDrawEvents=true;try{state.draw.deleteAll()}finally{state.suppressDrawEvents=false}state.editingDrawId=null}
function startPolygon(){if(!state.workspace){toast('Escolha um Polo e pelo menos um Livro.');return}if(!state.draw){toast('Ferramenta de desenho indisponível.');return}clearDrawEditor();clearPolygonSelection();state.draw.changeMode('draw_polygon');$('mapHint').textContent='Desenhe uma nova demarcação. Feche o polígono no primeiro ponto.'}
async function onDrawCreate(e){if(state.suppressDrawEvents)return;const feature=e.features?.[0];if(!feature)return;const defaultName=`Área ${state.demarcations.size+1}`;const name=prompt('Nome da demarcação:',defaultName)??defaultName;const color=DEMARCATION_COLORS[state.demarcations.size%DEMARCATION_COLORS.length];try{const plan=await ensurePlan();if(!plan)return;const saved=await api(`/api/plans/${plan.id}/demarcations`,{method:'POST',body:JSON.stringify({name,color,geometry:feature.geometry})});state.demarcations.set(Number(saved.id),saved);state.visibleDemarcations.add(Number(saved.id));clearDrawEditor();renderDemarcations();renderDemarcationLayers();refreshDemarcationSource();analyzeDemarcation(Number(saved.id));toast(`${saved.name} salva.`)}catch(err){toast(err.message)}}
async function onDrawUpdate(e){if(state.suppressDrawEvents||!state.editingDrawId)return;const feature=e.features?.[0];const d=state.demarcations.get(Number(state.editingDrawId));if(!feature||!d)return;try{const updated=await api(`/api/demarcations/${d.id}`,{method:'PUT',body:JSON.stringify({name:d.name,color:d.color,geometry:feature.geometry})});state.demarcations.set(Number(d.id),updated);refreshDemarcationSource();analyzeDemarcation(Number(d.id),false)}catch(err){toast(err.message)}}
function onDrawDelete(){if(state.suppressDrawEvents)return;state.editingDrawId=null}
function loadPlanDemarcations(){state.demarcations.clear();state.visibleDemarcations.clear();for(const d of state.plan?.demarcations||[]){state.demarcations.set(Number(d.id),d);state.visibleDemarcations.add(Number(d.id))}clearDrawEditor();renderDemarcations();renderDemarcationLayers();refreshDemarcationSource()}
function demarcationFeature(d){return {type:'Feature',id:Number(d.id),properties:{id:Number(d.id),name:d.name,color:d.color},geometry:d.geometry}}
function refreshDemarcationSource(){if(!state.mapReady)return;const features=[...state.demarcations.values()].filter(d=>state.visibleDemarcations.has(Number(d.id))).map(demarcationFeature);state.map.getSource('demarcations').setData({type:'FeatureCollection',features})}
function ucsInsideGeometry(geometry){if(!state.workspace||!geometry)return[];const fc={type:'FeatureCollection',features:state.workspace.ucs.features.filter(f=>state.selectedBooks.has(Number(f.properties.livro)))};try{return turf.pointsWithinPolygon(fc,{type:'Feature',properties:{},geometry}).features.map(f=>Number(f.properties.id))}catch{return[]}}
function overlapCount(ids,currentId){let count=0;for(const id of ids){const f=state.ucById.get(id);if(!f?.geometry)continue;let memberships=0;for(const d of state.demarcations.values()){if(Number(d.id)===Number(currentId))continue;try{if(turf.booleanPointInPolygon(f,demarcationFeature(d)))memberships++}catch{}}if(memberships)count++}return count}
function analyzeDemarcation(id,fit=true){const d=state.demarcations.get(Number(id));if(!d)return;state.currentDemarcationId=Number(id);state.polygonFound=ucsInsideGeometry(d.geometry);state.polygonChecked=new Set();const overlap=overlapCount(state.polygonFound,id);$('polygonTitle').textContent=d.name;$('polygonSummary').textContent=`${state.polygonFound.length.toLocaleString('pt-BR')} encontradas${overlap?` • ${overlap} sobrepostas`:''}`;renderPolygonSelection();updatePolygonHighlights();$('polygonPanel').classList.remove('hidden');if(fit&&state.mapReady){const b=geometryBounds(d.geometry);if(b)state.map.fitBounds(b,{padding:80,maxZoom:17})}$('mapHint').textContent=`${d.name}: ${state.polygonFound.length.toLocaleString('pt-BR')} UCs dentro da área.`}
function geometryBounds(geometry){const ring=geometry?.coordinates?.[0];if(!ring?.length)return null;const b=new maplibregl.LngLatBounds();ring.forEach(c=>b.extend(c));return b}
function editDemarcation(id){const d=state.demarcations.get(Number(id));if(!d||!state.draw)return;clearDrawEditor();const drawId=state.draw.add({type:'Feature',properties:{},geometry:d.geometry})[0];state.editingDrawId=Number(id);try{state.draw.changeMode('direct_select',{featureId:drawId})}catch{};analyzeDemarcation(id);toast('Arraste os vértices para editar a demarcação.')}
async function renameDemarcation(id){const d=state.demarcations.get(Number(id));if(!d)return;const name=prompt('Novo nome da demarcação:',d.name);if(name===null)return;try{const updated=await api(`/api/demarcations/${d.id}`,{method:'PUT',body:JSON.stringify({name:name.trim()||d.name,color:d.color,geometry:d.geometry})});state.demarcations.set(Number(id),updated);renderDemarcations();renderDemarcationLayers();refreshDemarcationSource();if(state.currentDemarcationId===Number(id))$('polygonTitle').textContent=updated.name}catch(e){toast(e.message)}}
async function deleteDemarcation(id){const d=state.demarcations.get(Number(id));if(!d||!confirm(`Excluir a demarcação "${d.name}"?`))return;try{await api(`/api/demarcations/${id}`,{method:'DELETE'});state.demarcations.delete(Number(id));state.visibleDemarcations.delete(Number(id));if(state.currentDemarcationId===Number(id))clearPolygonSelection();if(state.editingDrawId===Number(id))clearDrawEditor();renderDemarcations();renderDemarcationLayers();refreshDemarcationSource()}catch(e){toast(e.message)}}
function renderDemarcations(){const box=$('demarcationsList');const list=[...state.demarcations.values()];if(!list.length){box.className='demarcations-list muted';box.textContent='Nenhuma demarcação.';return}box.className='demarcations-list';box.innerHTML=list.map(d=>{const total=ucsInsideGeometry(d.geometry).length;return `<div class="demarcation-card"><div class="row"><span class="color-swatch" style="background:${d.color}"></span><span class="name">${esc(d.name)}</span><b>${total} UCs</b></div><div class="actions"><button class="mini-btn dem-view" data-id="${d.id}">Analisar</button><button class="mini-btn dem-edit" data-id="${d.id}">Editar</button><button class="mini-btn dem-rename" data-id="${d.id}">Renomear</button><button class="mini-btn dem-delete" data-id="${d.id}">Excluir</button></div></div>`}).join('');box.querySelectorAll('.dem-view').forEach(b=>b.onclick=()=>analyzeDemarcation(Number(b.dataset.id)));box.querySelectorAll('.dem-edit').forEach(b=>b.onclick=()=>editDemarcation(Number(b.dataset.id)));box.querySelectorAll('.dem-rename').forEach(b=>b.onclick=()=>renameDemarcation(Number(b.dataset.id)));box.querySelectorAll('.dem-delete').forEach(b=>b.onclick=()=>deleteDemarcation(Number(b.dataset.id)))}
function clearPolygonSelection(){state.currentDemarcationId=null;state.polygonFound=[];state.polygonChecked.clear();$('polygonPanel').classList.add('hidden');if(state.mapReady){state.map.getSource('polygon-found').setData(emptyFC());state.map.getSource('polygon-selected').setData(emptyFC())}}
function closePolygonPanel(){state.polygonFound=[];state.polygonChecked.clear();$('polygonPanel').classList.add('hidden');if(state.mapReady){state.map.getSource('polygon-found').setData(emptyFC());state.map.getSource('polygon-selected').setData(emptyFC())}}
function assignmentFor(id){return state.assigned.get(Number(id))||null}
function renderPolygonSelection(){const d=state.currentDemarcationId?state.demarcations.get(state.currentDemarcationId):null;if(d)$('polygonTitle').textContent=d.name;if(!d)$('polygonSummary').textContent=`${state.polygonFound.length.toLocaleString('pt-BR')} encontradas`;$('polygonCheckedCount').textContent=state.polygonChecked.size;const q=$('polygonSearch').value.trim().toLowerCase();const filtered=state.polygonFound.filter(id=>{const p=state.ucById.get(id)?.properties||{};return !q||String(p.uc).toLowerCase().includes(q)||String(p.rota).toLowerCase().includes(q)||String(p.livro).includes(q)||String(p.nome_localidade||p.localidade||'').toLowerCase().includes(q)});const box=$('polygonList');box.innerHTML='';for(const id of filtered){const f=state.ucById.get(id),p=f?.properties||{},a=assignmentFor(id);const row=document.createElement('label');row.className='polygon-row'+(a&&a.route_id!==state.editingRouteId?' assigned':'');row.innerHTML=`<input type="checkbox" ${state.polygonChecked.has(id)?'checked':''}><span><b>UC ${esc(p.uc||id)}</b> • Livro ${esc(p.livro)} • Rota ${esc(p.rota||'—')}<small>${esc(p.nome_localidade||p.localidade||'')}${a?`<br><span class="assigned-tag">Planejada: ${esc(a.leiturista||'sem leiturista')} • Rota ${esc(a.rota_nova)}</span>`:''}</small></span>`;const chk=row.querySelector('input');chk.onchange=()=>{chk.checked?state.polygonChecked.add(id):state.polygonChecked.delete(id);$('polygonCheckedCount').textContent=state.polygonChecked.size;updatePolygonHighlights()};box.appendChild(row)}}
function updatePolygonHighlights(){if(!state.mapReady)return;const found=state.polygonFound.map(id=>state.ucById.get(id)).filter(f=>f?.geometry);const selected=[...state.polygonChecked].map(id=>state.ucById.get(id)).filter(f=>f?.geometry);state.map.getSource('polygon-found').setData({type:'FeatureCollection',features:found});state.map.getSource('polygon-selected').setData({type:'FeatureCollection',features:selected})}
function selectAllPolygonUcs(){state.polygonChecked=new Set(state.polygonFound.map(Number));renderPolygonSelection();updatePolygonHighlights()}
function clearPolygonChecked(){state.polygonChecked.clear();renderPolygonSelection();updatePolygonHighlights()}

function featureCoordsById(id){return state.ucById.get(Number(id))?.geometry?.coordinates}
function handleUcClick(feature){const id=Number(feature.properties.id);const a=assignmentFor(id);if(a&&a.route_id!==state.editingRouteId){openConflictModal([id],()=>addManyToSequence([id],true));return}addManyToSequence([id],false)}
function addManyToSequence(ids,moveConflicts=false){for(const raw of ids){const id=Number(raw);if(!state.sequence.includes(id))state.sequence.push(id)}if(moveConflicts)state.moveConflictsOnSave=true;sequenceChanged()}
function removeSeq(index){state.sequence.splice(index,1);sequenceChanged()}
function sequenceChanged(){renderSequence();updateSequenceMap();state.dirty=true;scheduleAutosave()}
function renderSequence(){const c=$('seqCount');if(c)c.textContent=`${state.sequence.length} UCs`;const ol=$('sequenceList');ol.innerHTML='';if(!state.sequence.length){ol.innerHTML='<li class="empty">Clique nas UCs no mapa ou use uma demarcação.</li>';return}state.sequence.forEach((id,i)=>{const p=state.ucById.get(id)?.properties||{};const li=document.createElement('li');li.draggable=true;li.dataset.index=i;li.innerHTML=`<span class="idx">${i+1}</span><span><b>UC ${esc(p.uc||id)}</b><br><small>Livro ${esc(p.livro||'—')} • Rota atual ${esc(p.rota||'—')} • ${esc(p.nome_localidade||p.localidade||'')}</small></span><button class="remove">×</button>`;li.querySelector('.remove').onclick=()=>removeSeq(i);li.ondragstart=e=>e.dataTransfer.setData('text/plain',i);li.ondragover=e=>e.preventDefault();li.ondrop=e=>{e.preventDefault();const from=Number(e.dataTransfer.getData('text/plain'));const[x]=state.sequence.splice(from,1);state.sequence.splice(i,0,x);sequenceChanged()};ol.appendChild(li)})}
function updateSequenceMap(){if(!state.mapReady)return;const coords=state.sequence.map(featureCoordsById).filter(Boolean);state.map.getSource('sequence-line').setData(coords.length>1?{type:'FeatureCollection',features:[{type:'Feature',properties:{},geometry:{type:'LineString',coordinates:coords}}]}:emptyFC());state.map.getSource('sequence-points').setData({type:'FeatureCollection',features:coords.map((c,i)=>({type:'Feature',properties:{order:i+1},geometry:{type:'Point',coordinates:c}}))})}

function refreshUcSource(){if(!state.mapReady||!state.workspace)return;const features=state.workspace.ucs.features.filter(f=>state.visibleBooks.has(Number(f.properties.livro))).map(f=>{const copy={...f,properties:{...f.properties}};const a=assignmentFor(copy.properties.id);copy.properties.assigned=Boolean(a);copy.properties.displayColor=a?routeColor(a.route_id):copy.properties.color;return copy}).filter(f=>f.properties.assigned?state.showPlannedPoints:state.showPendingPoints);state.map.getSource('ucs').setData({type:'FeatureCollection',features})}
function renderSavedRoutes(){const feats=[];state.assigned.clear();for(const r of state.plan?.routes||[]){const coords=[];for(const it of r.items||[]){state.assigned.set(Number(it.uc_id),{route_id:Number(r.id),leiturista:r.leiturista,rota_nova:r.rota_nova,nome:r.nome,livro_novo:r.livro_novo});if(it.latitude!=null&&it.longitude!=null)coords.push([it.longitude,it.latitude])}if(coords.length>1)feats.push({type:'Feature',properties:{route_id:Number(r.id),color:routeColor(r.id)},geometry:{type:'LineString',coordinates:coords}})}if(state.mapReady)state.map.getSource('saved-routes').setData({type:'FeatureCollection',features:feats});applyLayerFilters();renderPlannedCards();renderPlannedLayers();if(!$('polygonPanel').classList.contains('hidden'))renderPolygonSelection();updatePlanningCoverage()}

async function loadInitial(){try{const h=await api('/api/health');status(`${h.ucs.toLocaleString('pt-BR')} UCs • V${h.version}`);await loadPolos()}catch(e){status('Backend indisponível');toast(e.message)}$('dateInput').value=new Date().toISOString().slice(0,10)}
async function loadPolos(){const list=await api('/api/polos');$('poloSelect').innerHTML='<option value="">Selecione</option>'+list.map(x=>`<option>${esc(x)}</option>`).join('')}
async function loadLivros(){const polo=$('poloSelect').value;state.availableBooks=[];state.selectedBooks.clear();state.visibleBooks.clear();renderBooksButton();const box=$('booksOptions');box.innerHTML='';if(!polo){box.className='books-options muted';box.textContent='Escolha um Polo.';return}const list=await api(`/api/livros?polo=${encodeURIComponent(polo)}`);state.availableBooks=list.map(Number);box.className='books-options';box.innerHTML=state.availableBooks.map(x=>`<label class="book-option"><span><input type="checkbox" class="book-choice" value="${x}"> Livro ${String(x).padStart(2,'0')}</span></label>`).join('')}
function renderBooksButton(){const a=selectedBooksArray();$('booksButton').textContent=a.length?(a.length<=3?a.map(x=>String(x).padStart(2,'0')).join(', '):`${a.length} Livros`):'Selecione'}
function syncBooksMenu(){document.querySelectorAll('.book-choice').forEach(ch=>ch.checked=state.selectedBooks.has(Number(ch.value)));renderBooksButton()}
async function applyBooksSelection(){const chosen=[...document.querySelectorAll('.book-choice:checked')].map(x=>Number(x.value));if(!chosen.length){toast('Selecione pelo menos um Livro.');return}state.selectedBooks=new Set(chosen);state.visibleBooks=new Set(chosen);renderBooksButton();$('booksMenu').classList.add('hidden');clearEditor();clearPolygonSelection();if(state.plan){try{state.plan=await api(`/api/plans/${state.plan.id}/books`,{method:'PUT',body:JSON.stringify({livros:chosen})});await loadWorkspace({preservePlan:true});loadPlanDemarcations();renderSavedRoutes();await refreshPlanOptions(state.plan.id)}catch(e){toast(e.message)}}else await loadWorkspace()}
async function loadWorkspace({preservePlan=false}={}){const polo=$('poloSelect').value,books=selectedBooksArray();if(!polo||!books.length)return;status('Carregando Livros…');if(!preservePlan){state.plan=null;state.assigned.clear();state.demarcations.clear();state.visibleDemarcations.clear()}try{const data=await api(`/api/workspace?polo=${encodeURIComponent(polo)}&livros=${books.join(',')}`);state.workspace=data;state.book=data;state.ucById.clear();for(const f of data.ucs.features)state.ucById.set(Number(f.properties.id),f);for(const x of data.no_coord)state.ucById.set(Number(x.id),{type:'Feature',properties:{id:x.id,uc:x.uc,rota:x.rota_atual,livro:x.livro_atual,route_key:routeKey(x.livro_atual,x.rota_atual),localidade:x.localidade,nome_localidade:x.nome_localidade},geometry:null});state.visibleRoutes=new Set();state.visibleBooks=new Set(books);$('newBookInput').value=books[0];applyWorkspaceMap(data);renderWorkspaceStats(data);renderBookLayers();renderRouteFilters();renderNoCoord();if(!preservePlan)await loadPlans();await loadWeather();status(`${data.total.toLocaleString('pt-BR')} UCs • ${books.length} Livro(s)`)}catch(e){toast(e.message);status('Erro ao carregar área de trabalho')}}
function applyWorkspaceMap(d){if(!state.mapReady){setTimeout(()=>applyWorkspaceMap(d),120);return}state.map.getSource('book-area').setData(d.book_areas);state.map.getSource('route-areas').setData(d.route_areas);state.map.getSource('road-preview').setData(emptyFC());refreshUcSource();applyLayerFilters();if(d.ucs.features.length){const b=new maplibregl.LngLatBounds();d.ucs.features.forEach(f=>b.extend(f.geometry.coordinates));state.bookBounds=b;state.map.fitBounds(b,{padding:55,maxZoom:15,duration:0})}}
function renderWorkspaceStats(d){$('statBooks').textContent=d.livros.length;$('statTotal').textContent=d.total.toLocaleString('pt-BR');$('statGps').textContent=d.with_coord.toLocaleString('pt-BR');$('statNoGps').textContent=d.without_coord.toLocaleString('pt-BR');updatePlanningCoverage()}
function updatePlanningCoverage(){const ids=new Set(state.ucById.keys()),assigned=[...state.assigned.keys()].filter(id=>ids.has(id)).length,total=Number(state.workspace?.total||0);$('statAssigned').textContent=assigned.toLocaleString('pt-BR');$('statPending').textContent=Math.max(0,total-assigned).toLocaleString('pt-BR')}

function renderBookLayers(){const box=$('bookLayers');if(!state.workspace){box.textContent='Selecione Livros.';return}box.className='layer-list';box.innerHTML=state.workspace.books.map(b=>`<label class="layer-row"><input type="checkbox" class="book-layer-check" value="${b.livro}" ${state.visibleBooks.has(Number(b.livro))?'checked':''}><span class="color-swatch" style="background:${b.color}"></span><span class="grow">Livro ${String(b.livro).padStart(2,'0')} • ${b.total} UCs</span></label>`).join('');box.querySelectorAll('.book-layer-check').forEach(ch=>ch.onchange=()=>{ch.checked?state.visibleBooks.add(Number(ch.value)):state.visibleBooks.delete(Number(ch.value));applyLayerFilters()})}
function renderRouteFilters(){const box=$('routeFilters');if(!state.workspace){box.textContent='Todas começam ocultas.';return}box.innerHTML='';for(const book of state.workspace.books){const group=document.createElement('div');group.className='route-book-group';const routes=state.workspace.routes.filter(r=>Number(r.livro)===Number(book.livro));group.innerHTML=`<div class="route-book-head"><b>Livro ${String(book.livro).padStart(2,'0')}</b><button class="mini-btn show-book-routes" data-book="${book.livro}">Mostrar todas</button></div><div class="route-book-body"></div>`;const body=group.querySelector('.route-book-body');for(const r of routes){const row=document.createElement('div');row.className='route-chip'+(state.visibleRoutes.has(r.route_key)?'':' off');row.dataset.route=r.route_key;row.innerHTML=`<span class="dot" style="background:${r.color}"></span><span><b>Rota ${esc(r.rota||'0')}</b><br>${r.total} UCs • ${r.with_coord} GPS</span><span class="route-actions"><button class="mini-btn isolate-route" title="Isolar">Isolar</button></span>`;row.onclick=e=>{if(e.target.closest('.isolate-route'))return;const k=r.route_key;state.visibleRoutes.has(k)?state.visibleRoutes.delete(k):state.visibleRoutes.add(k);row.classList.toggle('off',!state.visibleRoutes.has(k));applyLayerFilters()};row.querySelector('.isolate-route').onclick=()=>isolateRoute(r.route_key);body.appendChild(row)}group.querySelector('.show-book-routes').onclick=()=>{for(const r of routes)state.visibleRoutes.add(r.route_key);renderRouteFilters();applyLayerFilters()};box.appendChild(group)}}
function renderDemarcationLayers(){const box=$('demarcationLayers');const list=[...state.demarcations.values()];if(!list.length){box.className='layer-list muted';box.textContent='Nenhuma.';return}box.className='layer-list';box.innerHTML=list.map(d=>`<label class="layer-row"><input type="checkbox" class="dem-layer-check" value="${d.id}" ${state.visibleDemarcations.has(Number(d.id))?'checked':''}><span class="color-swatch" style="background:${d.color}"></span><span class="grow">${esc(d.name)}</span></label>`).join('');box.querySelectorAll('.dem-layer-check').forEach(ch=>ch.onchange=()=>{ch.checked?state.visibleDemarcations.add(Number(ch.value)):state.visibleDemarcations.delete(Number(ch.value));refreshDemarcationSource()})}
function renderPlannedLayers(){const box=$('plannedLayers'),routes=state.plan?.routes||[];if(!routes.length){box.className='layer-list muted';box.textContent='Nenhuma rota.';return}box.className='layer-list';box.innerHTML=routes.map(r=>`<label class="layer-row"><input type="checkbox" class="planned-layer-check" value="${r.id}" ${state.visiblePlannedRoutes.has(Number(r.id))?'checked':''}><span class="color-swatch" style="background:${routeColor(r.id)}"></span><span class="grow">${esc(r.leiturista||'Sem leiturista')} • Rota ${esc(r.rota_nova)}</span></label>`).join('');box.querySelectorAll('.planned-layer-check').forEach(ch=>ch.onchange=()=>{ch.checked?state.visiblePlannedRoutes.add(Number(ch.value)):state.visiblePlannedRoutes.delete(Number(ch.value));applyLayerFilters()})}
function applyLayerFilters(){if(!state.mapReady||!state.workspace)return;refreshUcSource();const books=[...state.visibleBooks],routes=[...state.visibleRoutes],planned=[...state.visiblePlannedRoutes];state.map.setFilter('book-fill',['in',['get','livro'],['literal',books]]);state.map.setFilter('book-outline',['in',['get','livro'],['literal',books]]);state.map.setFilter('route-fill',['in',['get','route_key'],['literal',routes]]);state.map.setFilter('route-outline',['in',['get','route_key'],['literal',routes]]);state.map.setFilter('saved-routes',['in',['get','route_id'],['literal',planned]]);refreshDemarcationSource();renderBookLayers()}
function isolateRoute(key){if(!state.workspace)return;if(!state.isolatedSnapshot)state.isolatedSnapshot={visibleBooks:new Set(state.visibleBooks),visibleRoutes:new Set(state.visibleRoutes),showPendingPoints:state.showPendingPoints,showPlannedPoints:state.showPlannedPoints};const [book]=String(key).split('::');state.visibleBooks=new Set([Number(book)]);state.visibleRoutes=new Set([String(key)]);$('restoreViewBtn').classList.remove('hidden');applyLayerFilters();renderRouteFilters();toast(`Visualização isolada: Livro ${book} / Rota ${String(key).split('::')[1]}`)}
function restoreLayerView(){if(!state.isolatedSnapshot)return;state.visibleBooks=new Set(state.isolatedSnapshot.visibleBooks);state.visibleRoutes=new Set(state.isolatedSnapshot.visibleRoutes);state.showPendingPoints=state.isolatedSnapshot.showPendingPoints;state.showPlannedPoints=state.isolatedSnapshot.showPlannedPoints;state.isolatedSnapshot=null;$('restoreViewBtn').classList.add('hidden');$('showPendingPoints').checked=state.showPendingPoints;$('showPlannedPoints').checked=state.showPlannedPoints;applyLayerFilters();renderRouteFilters()}
function renderNoCoord(){const box=$('noCoordBox');if(!state.workspace?.no_coord?.length){box.innerHTML='Nenhuma UC sem coordenada.';return}box.innerHTML=state.workspace.no_coord.slice(0,500).map(x=>`<div class="no-coord-item">UC <b>${esc(x.uc)}</b> • Livro ${esc(x.livro_atual)} • Rota ${esc(x.rota_atual)} <button class="mini-btn add-nogps" data-id="${x.id}">Adicionar</button></div>`).join('');box.querySelectorAll('.add-nogps').forEach(b=>b.onclick=()=>addManyToSequence([Number(b.dataset.id)]))}
function searchUc(){const q=$('ucSearchInput').value.trim().toLowerCase();if(!q){toast('Digite uma UC.');return}let exact=null,partial=null;for(const f of state.ucById.values()){const uc=String(f.properties?.uc||'').toLowerCase();if(uc===q){exact=f;break}if(!partial&&uc.includes(q))partial=f}const f=exact||partial;if(!f){toast('UC não encontrada nos Livros selecionados.');return}if(!f.geometry){toast(`UC ${f.properties.uc} encontrada, mas sem coordenada.`);return}state.searchFeatureId=Number(f.properties.id);state.map.getSource('search-highlight').setData({type:'FeatureCollection',features:[f]});state.map.easeTo({center:f.geometry.coordinates,zoom:18});new maplibregl.Popup().setLngLat(f.geometry.coordinates).setHTML(`<b>UC ${esc(f.properties.uc)}</b><br>Livro ${esc(f.properties.livro)} • Rota ${esc(f.properties.rota)}`).addTo(state.map)}

async function refreshPlanOptions(selectedId=null){const polo=$('poloSelect').value;if(!polo)return;const list=await api(`/api/plans?polo=${encodeURIComponent(polo)}`);$('planSelect').innerHTML='<option value="">Novo</option>'+list.map(p=>`<option value="${p.id}">${esc(p.name)} • Livros ${(p.livros||[p.livro_origem]).map(x=>String(x).padStart(2,'0')).join(', ')} • ${esc(p.planned_date)}</option>`).join('');if(selectedId)$('planSelect').value=String(selectedId)}
async function loadPlans(preferred=null){await refreshPlanOptions(preferred);if(preferred)await selectPlan(Number(preferred));else{state.plan=null;state.assigned.clear();state.demarcations.clear();state.visibleDemarcations.clear();state.visiblePlannedRoutes.clear();renderSavedRoutes();renderDemarcations();renderDemarcationLayers();refreshDemarcationSource();updateExport();refreshBalance()}}
async function selectPlan(id){if(!id){state.plan=null;clearEditor();state.demarcations.clear();state.visibleDemarcations.clear();state.visiblePlannedRoutes.clear();renderSavedRoutes();renderDemarcations();renderDemarcationLayers();refreshDemarcationSource();updateExport();refreshBalance();return}const plan=await api(`/api/plans/${id}`);if(!sameBooks(plan.livros||[plan.livro_origem],state.selectedBooks)){state.selectedBooks=new Set(plan.livros||[plan.livro_origem]);syncBooksMenu();await loadWorkspace({preservePlan:true})}state.plan=plan;$('planSelect').value=String(id);$('dateInput').value=state.plan.planned_date;$('minutesPerUcInput').value=state.plan.minutes_per_uc;$('marginPctInput').value=state.plan.margin_pct;state.visiblePlannedRoutes=new Set((state.plan.routes||[]).map(r=>Number(r.id)));loadPlanDemarcations();renderSavedRoutes();updateExport();clearEditor();refreshBalance();loadWeather()}
async function createPlan(nameOverride){const polo=$('poloSelect').value,books=selectedBooksArray();if(!polo||!books.length)throw new Error('Escolha Polo e pelo menos um Livro.');let name=nameOverride;if(name===undefined){name=prompt('Nome do planejamento:',`${polo} - Livros ${books.map(x=>String(x).padStart(2,'0')).join(', ')}`);if(name===null)return null}const p=await api('/api/plans',{method:'POST',body:JSON.stringify({name,polo,livro:books[0],livros:books,planned_date:$('dateInput').value})});state.plan=await api(`/api/plans/${p.id}/settings`,{method:'PUT',body:JSON.stringify({minutes_per_uc:Number($('minutesPerUcInput').value)||1.4,margin_pct:Number($('marginPctInput').value)||10})});state.visiblePlannedRoutes=new Set();loadPlanDemarcations();await refreshPlanOptions(p.id);renderSavedRoutes();updateExport();return state.plan}
async function ensurePlan(){if(state.plan)return state.plan;const books=selectedBooksArray();return createPlan(`${$('poloSelect').value} - Livros ${books.map(x=>String(x).padStart(2,'0')).join(', ')} - ${$('dateInput').value}`)}
function updateExport(){if(state.plan){$('exportBtn').href=`/api/plans/${state.plan.id}/export`;$('exportBtn').classList.remove('disabled')}else $('exportBtn').classList.add('disabled')}
function renderPlannedCards(){const box=$('plannedRoutes'),routes=state.plan?.routes||[];if(!routes.length){box.className='planned-list muted';box.innerHTML='Nenhuma rota planejada.';return}box.className='planned-list';box.innerHTML='';for(const r of routes){const card=document.createElement('div');card.className='planned-card'+(state.editingRouteId===r.id?' active':'');card.innerHTML=`<b>${esc(r.nome||'Nova rota')} — ${esc(r.leiturista||'sem leiturista')}</b><small>Livro ${r.livro_novo} • Rota ${esc(r.rota_nova||'—')} • ${r.items.length} UCs • ${r.modo==='WALK'?'A pé':'Moto'}</small>`;card.onclick=()=>editRoute(r.id);box.appendChild(card)}}
function editRoute(id){const r=state.plan?.routes?.find(x=>x.id===id);if(!r)return;state.editingRouteId=id;$('readerInput').value=r.leiturista;$('modeSelect').value=r.modo;$('newBookInput').value=r.livro_novo;$('newRouteInput').value=r.rota_nova;$('routeNameInput').value=r.nome;state.sequence=r.items.map(x=>Number(x.uc_id));state.moveConflictsOnSave=false;renderSequence();updateSequenceMap();renderPlannedCards();setAutosave('Salvo','saved')}
function clearEditor(){clearTimeout(state.autosaveTimer);state.editingRouteId=null;state.sequence=[];state.moveConflictsOnSave=false;$('readerInput').value='';$('newRouteInput').value=nextRouteNumber();$('routeNameInput').value='';const books=selectedBooksArray();if(books.length)$('newBookInput').value=books[0];renderSequence();updateSequenceMap();renderPlannedCards();if(state.mapReady)state.map.getSource('road-preview').setData(emptyFC());setAutosave('Local')}
function nextRouteNumber(){const nums=(state.plan?.routes||[]).map(r=>parseInt(r.rota_nova,10)).filter(Number.isFinite);return String((nums.length?Math.max(...nums):0)+1).padStart(2,'0')}
function routePayload(move=state.moveConflictsOnSave){const books=selectedBooksArray();return {nome:$('routeNameInput').value||`Rota ${$('newRouteInput').value||nextRouteNumber()}`,leiturista:$('readerInput').value.trim(),modo:$('modeSelect').value,livro_novo:Number($('newBookInput').value||books[0]||0),rota_nova:$('newRouteInput').value||nextRouteNumber(),uc_ids:state.sequence,move_conflicts:Boolean(move)}}
function scheduleAutosave(){clearTimeout(state.autosaveTimer);if(!state.sequence.length&&!state.editingRouteId)return;setAutosave('Alterado','saving');state.autosaveTimer=setTimeout(()=>saveRoute({silent:true}),800)}
async function saveRoute({silent=false,force=false}={}){if(state.saveInFlight)return;if(!state.sequence.length&&!state.editingRouteId){if(!silent)toast('Selecione pelo menos uma UC.');return}state.saveInFlight=true;setAutosave('Salvando…','saving');try{const plan=await ensurePlan();if(!plan)return;const payload=routePayload();const wasNew=!state.editingRouteId;if(wasNew){const before=new Set((state.plan?.routes||[]).map(r=>r.id));state.plan=await api(`/api/plans/${plan.id}/routes`,{method:'POST',body:JSON.stringify(payload)});const created=state.plan.routes.filter(r=>!before.has(r.id)).sort((a,b)=>b.id-a.id)[0];state.editingRouteId=created?.id||state.plan.routes.at(-1)?.id;if(state.editingRouteId)state.visiblePlannedRoutes.add(Number(state.editingRouteId))}else state.plan=await api(`/api/routes/${state.editingRouteId}`,{method:'PUT',body:JSON.stringify(payload)});state.moveConflictsOnSave=false;state.dirty=false;renderSavedRoutes();updateExport();await refreshBalance();setAutosave(`Salvo ${new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}`,'saved');if(!silent)toast('Rota salva.')}catch(e){setAutosave('Pendente','error');if(e.status===409&&e.detail?.code==='UC_ASSIGNED'){openConflictModal(e.detail.conflicts.map(x=>Number(x.uc_id)),async()=>{state.moveConflictsOnSave=true;await saveRoute({silent:false,force:true})})}else if(!silent||force)toast(e.message)}finally{state.saveInFlight=false}}

async function suggestSelectedPolygon(){const ids=[...state.polygonChecked];if(!ids.length){toast('Marque pelo menos uma UC.');return}try{const r=await api('/api/sequence/suggest',{method:'POST',body:JSON.stringify({uc_ids:ids,start_id:null})});showOrderPreview(r,'polygon')}catch(e){toast(e.message)}}
async function optimizeRoads(){const ids=state.sequence.length?state.sequence:[...state.polygonChecked];if(ids.length<2){toast('Selecione pelo menos duas UCs.');return}const estimatedRequests=Math.max(1,Math.ceil((ids.length-1)/26));if(!confirm(`Otimizar ${ids.length} UCs pelas vias? O sistema poderá fazer aproximadamente ${estimatedRequests} requisição(ões) à Google Routes quando a chave estiver configurada.`))return;try{status('Otimizando pelas vias…');const r=await api('/api/sequence/optimize',{method:'POST',body:JSON.stringify({uc_ids:ids,start_id:ids[0],mode:$('modeSelect').value})});showOrderPreview(r,state.sequence.length?'sequence':'polygon');if(r.geometry?.length&&state.mapReady)state.map.getSource('road-preview').setData({type:'FeatureCollection',features:[{type:'Feature',properties:{},geometry:{type:'LineString',coordinates:r.geometry}}]});status('Otimização pronta')}catch(e){toast(e.message);status('Erro na otimização')}}
function showOrderPreview(result,context){state.previewOrder=(result.order||[]).map(Number);state.previewContext=context;const provider=result.provider||'LOCAL_GEOGRAPHIC';const list=state.previewOrder.slice(0,120).map((id,i)=>{const p=state.ucById.get(id)?.properties||{};return `<div>${i+1}. UC ${esc(p.uc||id)}</div>`}).join('');$('orderBody').innerHTML=`<p><b>${esc(provider)}</b></p><p>${state.previewOrder.length} UCs • distância sugerida ${fmtKm(result.distance_m??result.local_distance_m)}${result.duration_s!=null?` • ${fmtMin(result.duration_s/60)}`:''}</p>${result.requests?`<p>${result.requests} bloco(s)/requisição(ões) viárias.</p>`:''}${result.warning?`<p class="muted">${esc(result.warning)}</p>`:''}<div class="order-preview">${list}${state.previewOrder.length>120?'<div>…</div>':''}</div>`;openModal('orderModal')}
function applyPreviewOrder(){const ids=state.previewOrder.slice();closeModals();if(state.previewContext==='sequence'){state.sequence=ids;sequenceChanged();return}handlePolygonAdd(ids)}
function handlePolygonAdd(orderOverride=null){const ids=(orderOverride||[...state.polygonChecked]).map(Number);if(!ids.length){toast('Marque pelo menos uma UC.');return}const conflicts=ids.filter(id=>{const a=assignmentFor(id);return a&&a.route_id!==state.editingRouteId});if(conflicts.length){openConflictModal(conflicts,()=>addManyToSequence(ids,true),()=>addManyToSequence(ids.filter(id=>!conflicts.includes(id)),false));return}addManyToSequence(ids,false)}
function openConflictModal(ids,onMove,onKeep=null){const conflicts=ids.map(id=>({id,a:assignmentFor(id),p:state.ucById.get(id)?.properties||{}})).filter(x=>x.a);$('conflictBody').innerHTML=`<p>Esta seleção contém <b>${conflicts.length}</b> UC(s) já atribuída(s) a outras rotas.</p>`+conflicts.slice(0,80).map(x=>`<div class="conflict-row"><b>UC ${esc(x.p.uc||x.id)}</b><br>${esc(x.a.leiturista||'sem leiturista')} • Rota nova ${esc(x.a.rota_nova)}</div>`).join('')+(conflicts.length>80?'<p>…</p>':'');$('conflictMoveBtn').onclick=()=>{closeModals();onMove?.()};$('conflictKeepBtn').onclick=()=>{closeModals();if(onKeep)onKeep();else toast('UC mantida na rota atual.')};openModal('conflictModal')}

async function refreshBalance(){const box=$('balanceBox');if(!state.plan){box.className='balance-box muted';box.innerHTML='Selecione um planejamento para comparar as rotas.';return}try{const b=await api(`/api/plans/${state.plan.id}/balance`);if(!b.routes.length){box.className='balance-box muted';box.textContent='Nenhuma rota planejada.';return}box.className='balance-box';box.innerHTML=b.routes.map(r=>`<div class="route-metric"><strong>${esc(r.leiturista||'Sem leiturista')} • Rota ${esc(r.rota_nova)}</strong>${r.uc_count} UCs • ${fmtKm(r.distance_m)} • ${fmtMin(r.total_minutes)}</div>`).join('')+(b.warning?`<div class="balance-warning">⚠ ${esc(b.warning)}</div>`:'')}catch(e){box.textContent=e.message}}
function scheduleSettingsSave(){clearTimeout(state.settingsTimer);state.settingsTimer=setTimeout(saveSettings,650)}
async function saveSettings(){if(!state.plan)return;try{state.plan=await api(`/api/plans/${state.plan.id}/settings`,{method:'PUT',body:JSON.stringify({minutes_per_uc:Number($('minutesPerUcInput').value)||1.4,margin_pct:Number($('marginPctInput').value)||0})});await refreshBalance()}catch(e){toast(e.message)}}
async function createManualVersion(){if(!state.plan){toast('Selecione um planejamento.');return}const label=prompt('Nome desta versão/backup:','Antes de alteração importante');if(label===null)return;try{await api(`/api/plans/${state.plan.id}/versions`,{method:'POST',body:JSON.stringify({label})});toast('Versão criada.')}catch(e){toast(e.message)}}
async function openHistory(){if(!state.plan){toast('Selecione um planejamento.');return}openModal('historyModal');const box=$('historyBody');box.textContent='Carregando…';try{const versions=await api(`/api/plans/${state.plan.id}/versions`);if(!versions.length){box.textContent='Nenhuma versão registrada.';return}box.innerHTML=versions.map(v=>`<div class="history-row"><div><b>${esc(v.label||v.event||'Versão automática')}</b><br><small>${esc(v.kind)} • ${esc(v.created_at)}<br>${esc(v.event||'')}</small></div><div class="history-actions"><button class="mini-btn version-restore" data-id="${v.id}">Restaurar</button><button class="mini-btn version-copy" data-id="${v.id}">Criar cópia</button></div></div>`).join('');box.querySelectorAll('.version-restore').forEach(b=>b.onclick=()=>restoreVersion(Number(b.dataset.id),'restore'));box.querySelectorAll('.version-copy').forEach(b=>b.onclick=()=>restoreVersion(Number(b.dataset.id),'copy'))}catch(e){box.textContent=e.message}}
async function restoreVersion(id,mode){try{let copy_name=null;if(mode==='restore'){if(!confirm('Restaurar esta versão como estado atual? O histórico posterior será preservado.'))return}else{copy_name=prompt('Nome da nova cópia:','Cópia do planejamento');if(copy_name===null)return}const p=await api(`/api/versions/${id}/restore`,{method:'POST',body:JSON.stringify({mode,copy_name})});closeModals();state.selectedBooks=new Set(p.livros||[p.livro_origem]);syncBooksMenu();await loadWorkspace({preservePlan:true});await refreshPlanOptions(p.id);await selectPlan(p.id);toast(mode==='copy'?'Cópia criada.':'Versão restaurada.')}catch(e){toast(e.message)}}
function openModal(id){$('modalBackdrop').classList.remove('hidden');$(id).classList.remove('hidden')}
function closeModals(){$('modalBackdrop').classList.add('hidden');document.querySelectorAll('.modal').forEach(x=>x.classList.add('hidden'))}
async function loadWeather(){if(!state.workspace?.center||!$('dateInput').value)return;const b=$('weatherBox');b.textContent='Consultando…';try{const r=await api(`/api/weather?lat=${state.workspace.center.lat}&lon=${state.workspace.center.lon}&target_date=${$('dateInput').value}`);if(!r.forecast){b.innerHTML='Previsão indisponível.<br>'+r.errors.map(e=>`${esc(e.provider)}: falhou`).join('<br>');return}const f=r.forecast;b.innerHTML=`<b>${esc(f.provider)}</b><br>🌡 ${f.tmin??'—'}° / ${f.tmax??'—'}°C<br>🌧 ${f.rain_probability??'—'}% • ${f.rain_mm??'—'} mm<br>💨 ${f.wind_kmh!=null?Number(f.wind_kmh).toFixed(1):'—'} km/h`}catch(e){b.textContent='Clima indisponível: '+e.message}}
function haversineJs(a,b){const R=6371000,toRad=x=>x*Math.PI/180;const dLat=toRad(b[1]-a[1]),dLon=toRad(b[0]-a[0]),p1=toRad(a[1]),p2=toRad(b[1]);const x=Math.sin(dLat/2)**2+Math.cos(p1)*Math.cos(p2)*Math.sin(dLon/2)**2;return 2*R*Math.asin(Math.sqrt(x))}
function suggestNearby(){if(!state.sequence.length){toast('Selecione uma UC de referência.');return}const last=featureCoordsById(state.sequence.at(-1));if(!last){toast('A última UC não possui coordenada.');return}const blocked=new Set(state.sequence);for(const[id,a]of state.assigned){if(a.route_id!==state.editingRouteId)blocked.add(id)}const candidates=[];for(const[id,f]of state.ucById){if(blocked.has(id)||!f.geometry||!state.visibleBooks.has(Number(f.properties.livro)))continue;candidates.push({id,f,d:haversineJs(last,f.geometry.coordinates)})}candidates.sort((a,b)=>a.d-b.d);const top=candidates.slice(0,8),box=$('suggestBox');box.classList.remove('hidden');if(!top.length){box.textContent='Nenhuma UC disponível próxima.';return}box.innerHTML='<b>Próximas UCs não atribuídas</b>'+top.map(x=>`<div style="display:flex;justify-content:space-between;gap:8px;margin-top:6px"><span>UC ${esc(x.f.properties.uc)} • ${fmtKm(x.d)}</span><button class="mini-btn sug-add" data-id="${x.id}">Adicionar</button></div>`).join('');box.querySelectorAll('.sug-add').forEach(b=>b.onclick=()=>{addManyToSequence([Number(b.dataset.id)]);suggestNearby()})}

$('poloSelect').onchange=async()=>{state.plan=null;state.workspace=null;state.book=null;state.demarcations.clear();state.visibleRoutes=new Set();clearEditor();clearPolygonSelection();await loadLivros()};
$('booksButton').onclick=e=>{e.stopPropagation();$('booksMenu').classList.toggle('hidden')};
$('booksApplyBtn').onclick=()=>applyBooksSelection().catch(e=>toast(e.message));
document.addEventListener('click',e=>{if(!e.target.closest('.books-picker-wrap'))$('booksMenu').classList.add('hidden')});
$('dateInput').onchange=async()=>{loadWeather();if(state.plan){try{state.plan=await api(`/api/plans/${state.plan.id}`,{method:'PUT',body:JSON.stringify({planned_date:$('dateInput').value})})}catch(e){toast(e.message)}}};
$('planSelect').onchange=e=>selectPlan(Number(e.target.value)||null);
$('newPlanBtn').onclick=()=>createPlan().catch(e=>toast(e.message));
$('importBtn').onclick=async()=>{if(!confirm('Atualizar a base SQLite usando os TXT da rede?'))return;status('Importando TXT…');try{const r=await api('/api/import',{method:'POST',body:'{}'});toast(`${r.rows.toLocaleString('pt-BR')} linhas importadas.`);await loadPolos();status('Base atualizada')}catch(e){toast(e.message);status('Erro na importação')}};
$('drawPolygonBtn').onclick=startPolygon;$('closePolygonBtn').onclick=closePolygonPanel;$('polygonSearch').oninput=renderPolygonSelection;$('polygonSelectAllBtn').onclick=selectAllPolygonUcs;$('polygonClearSelectionBtn').onclick=clearPolygonChecked;$('polygonSuggestBtn').onclick=suggestSelectedPolygon;$('polygonAddBtn').onclick=()=>handlePolygonAdd();
$('hideAllRoutesBtn').onclick=()=>{state.visibleRoutes=new Set();renderRouteFilters();applyLayerFilters()};
$('showPendingPoints').onchange=e=>{state.showPendingPoints=e.target.checked;applyLayerFilters()};$('showPlannedPoints').onchange=e=>{state.showPlannedPoints=e.target.checked;applyLayerFilters()};
$('ucSearchBtn').onclick=searchUc;$('ucSearchInput').onkeydown=e=>{if(e.key==='Enter')searchUc()};$('restoreViewBtn').onclick=restoreLayerView;
$('undoBtn').onclick=()=>{state.sequence.pop();sequenceChanged()};$('reverseBtn').onclick=()=>{state.sequence.reverse();sequenceChanged()};$('clearSeqBtn').onclick=()=>{state.sequence=[];sequenceChanged()};$('newRouteBtn').onclick=clearEditor;
$('saveRouteBtn').onclick=()=>{if(!$('readerInput').value.trim()){toast('Informe o leiturista antes de salvar manualmente.');return}saveRoute({silent:false,force:true})};$('suggestBtn').onclick=suggestNearby;$('optimizeRoadsBtn').onclick=optimizeRoads;$('fitBtn').onclick=()=>{if(state.bookBounds)state.map.fitBounds(state.bookBounds,{padding:55,maxZoom:15})};
['readerInput','modeSelect','newBookInput','newRouteInput','routeNameInput'].forEach(id=>$(id).addEventListener('input',()=>{if(state.sequence.length)scheduleAutosave()}));$('minutesPerUcInput').oninput=scheduleSettingsSave;$('marginPctInput').oninput=scheduleSettingsSave;$('manualVersionBtn').onclick=createManualVersion;$('historyBtn').onclick=openHistory;$('applyOrderBtn').onclick=applyPreviewOrder;document.querySelectorAll('[data-close-modal]').forEach(b=>b.onclick=closeModals);$('modalBackdrop').onclick=closeModals;

if(typeof maplibregl==='undefined'){showMapDependencyError('MapLibre não carregou. Verifique acesso ao CDN/rede corporativa.')}else{initMap();loadInitial()}
